-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.trash_near(p_world uuid, p_uid uuid)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p
  where p.world_id = p_world and p.kind = 'furniture'
    and coalesce((select trash from furniture_def where id = p.sub), 0) > 0
    and near_piece(p_world, p_uid, p, 3)
  order by p.id limit 1
$function$
